// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 dt) public {
        vm.assume(caller != address(0));
        dt = bound(dt, 1, 100000);

        vm.deal(caller, 20 ether);

        uint256 before = block.timestamp;
        vm.warp(before + dt);

        uint256 targetBlock = block.number;
        if (targetBlock % 15 != 0) {
            uint256 add = 15 - (targetBlock % 15);
            vm.roll(targetBlock + add);
        }

        assert(block.number % 15 == 0);

        vm.prank(caller);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        uint256 balAfter = address(c).balance;

        assertTrue(balAfter == 0);
    }
}
